files.css:
:root{
  --g9:#0b3d2e;--g8:#0f5132;--g7:#177245;--g5:#2f9e6b;--g1:#e6f4ec;
  --gold:#c9a227;--gold2:#f3e3a6;
  --bg:#f3f6f1;--card:#fff;--tx:#1d2b24;--mut:#6b7c73;--line:#e3eae5;
  --red:#c0392b;--red1:#fdecea;--amb:#b7791f;--amb1:#fff4dc;--blue:#2b6cb0;
  --r:18px;--sh:0 2px 10px rgba(15,81,50,.08),0 1px 2px rgba(0,0,0,.04);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;height:100%;background:var(--bg);color:var(--tx);
  font-family:"Noto Naskh Arabic","Segoe UI",Tahoma,system-ui,sans-serif;font-size:15px;line-height:1.6;
  -webkit-user-select:none;user-select:none;overscroll-behavior:none}
input,select,textarea,button{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
#app{max-width:640px;margin:0 auto;height:100%;display:flex;flex-direction:column;position:relative}
header.top{background:linear-gradient(135deg,var(--g9),var(--g7));color:#fff;padding:calc(env(safe-area-inset-top) + 14px) 18px 18px;
  border-radius:0 0 26px 26px;box-shadow:0 6px 18px rgba(11,61,46,.25);position:relative;overflow:hidden;flex:none}
header.top:before{content:"";position:absolute;inset:-40% auto auto -20%;width:260px;height:260px;border-radius:50%;
  background:radial-gradient(circle,rgba(201,162,39,.35),transparent 65%)}
header.top h1{margin:0;font-size:19px;position:relative;display:flex;align-items:center;gap:10px}
header.top .sub{position:relative;opacity:.85;font-size:13px;margin-top:2px}
header .back{width:36px;height:36px;border-radius:12px;background:rgba(255,255,255,.15);display:grid;place-items:center}
#view{flex:1;overflow-y:auto;padding:14px 14px 110px;-webkit-overflow-scrolling:touch}
.enter{animation:enter .38s cubic-bezier(.2,.8,.2,1) both}
@keyframes enter{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.stagger>*{animation:enter .45s cubic-bezier(.2,.8,.2,1) both;animation-delay:calc(var(--i,0)*45ms)}
.card{background:var(--card);border-radius:var(--r);box-shadow:var(--sh);padding:14px;margin-bottom:12px}
.card h3{margin:0 0 10px;font-size:16px;display:flex;align-items:center;gap:8px;color:var(--g8)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.stat{border-radius:16px;padding:12px 14px;color:#fff;position:relative;overflow:hidden;box-shadow:var(--sh)}
.stat .n{font-size:26px;font-weight:800;line-height:1.2}
.stat .l{font-size:12.5px;opacity:.92}
.stat svg{position:absolute;left:8px;bottom:6px;width:46px;height:46px;opacity:.18}
.s1{background:linear-gradient(135deg,#0f5132,#2f9e6b)}.s2{background:linear-gradient(135deg,#a67c00,#e0b83a)}
.s3{background:linear-gradient(135deg,#1e6091,#3b8ed0)}.s4{background:linear-gradient(135deg,#a93226,#e0675b)}
.row{display:flex;align-items:center;gap:10px}
.sp{flex:1;min-width:0}
.ava{width:44px;height:44px;border-radius:14px;background:var(--g1);color:var(--g8);display:grid;place-items:center;font-weight:800;font-size:18px;flex:none}
.item{display:flex;gap:12px;align-items:center;padding:12px;background:var(--card);border-radius:16px;box-shadow:var(--sh);margin-bottom:10px;transition:transform .15s}
.item:active{transform:scale(.985)}
.item .t{font-weight:700}.item .m{font-size:12.5px;color:var(--mut)}
.chip{display:inline-block;padding:1px 10px;border-radius:99px;font-size:12px;background:var(--g1);color:var(--g8);margin:2px 0 0 4px}
.chip.red{background:var(--red1);color:var(--red)}.chip.amb{background:var(--amb1);color:var(--amb)}
.chip.gold{background:var(--gold2);color:#7a5c00}.chip.blue{background:#e5f0fa;color:var(--blue)}
.bar{height:7px;background:var(--line);border-radius:9px;overflow:hidden;margin-top:6px}
.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--g5),var(--gold));border-radius:9px;width:0;transition:width .9s cubic-bezier(.2,.8,.2,1)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 16px;border-radius:14px;background:var(--g8);color:#fff;font-weight:700;position:relative;overflow:hidden;transition:transform .12s}
.btn:active{transform:scale(.96)}
.btn.sec{background:var(--g1);color:var(--g8)}.btn.red{background:var(--red1);color:var(--red)}
.btn.gold{background:var(--gold);color:#fff}.btn.sm{padding:6px 12px;font-size:13px;border-radius:11px}
.btn.wa{background:#25a15a}.btn.call{background:var(--blue)}
.btn.block{display:flex;width:100%}
.ic{width:20px;height:20px;stroke:currentColor;fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round;flex:none}
.ibtn{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:var(--g1);color:var(--g8);flex:none}
.ibtn.wa{background:#e1f5e9;color:#1f8f4e}.ibtn.call{background:#e5f0fa;color:var(--blue)}.ibtn.red{background:var(--red1);color:var(--red)}
.ripple{position:absolute;border-radius:50%;background:rgba(255,255,255,.45);transform:scale(0);animation:rp .55s ease-out;pointer-events:none}
@keyframes rp{to{transform:scale(3.2);opacity:0}}
nav.bottom{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;max-width:640px;background:#fff;
  display:flex;padding:8px 6px calc(env(safe-area-inset-bottom) + 8px);box-shadow:0 -4px 18px rgba(0,0,0,.08);border-radius:22px 22px 0 0;z-index:20}
nav.bottom button{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;font-size:11.5px;color:var(--mut);padding:6px 0;border-radius:14px;position:relative;transition:color .2s}
nav.bottom button svg{transition:transform .25s}
nav.bottom button.on{color:var(--g8);font-weight:800}
nav.bottom button.on svg{transform:translateY(-3px) scale(1.12)}
nav.bottom button.on:after{content:"";position:absolute;top:0;width:26px;height:4px;border-radius:0 0 6px 6px;background:var(--gold)}
.fab{position:fixed;bottom:calc(env(safe-area-inset-bottom) + 84px);left:18px;width:58px;height:58px;border-radius:20px;
  background:linear-gradient(135deg,var(--g7),var(--g9));color:#fff;display:grid;place-items:center;box-shadow:0 8px 20px rgba(11,61,46,.4);z-index:19;animation:pop .5s cubic-bezier(.3,1.6,.5,1) both}
.fab:active{transform:scale(.92)}.fab .ic{width:26px;height:26px}
@keyframes pop{from{transform:scale(0) rotate(-90deg)}to{transform:none}}
.overlay{position:fixed;inset:0;background:rgba(10,30,20,.5);z-index:50;display:flex;align-items:flex-end;justify-content:center;animation:fade .2s both}
@keyframes fade{from{opacity:0}}
.sheet{background:#fff;width:100%;max-width:640px;max-height:92%;overflow-y:auto;border-radius:26px 26px 0 0;padding:18px 16px calc(env(safe-area-inset-bottom) + 20px);animation:up .32s cubic-bezier(.2,.9,.2,1) both;-webkit-user-select:text;user-select:text}
@keyframes up{from{transform:translateY(100%)}}
.sheet h2{margin:0 0 12px;font-size:18px;color:var(--g8)}
label.f{display:block;margin-bottom:12px;font-size:13px;color:var(--mut)}
label.f>span{display:block;margin-bottom:4px}
input[type=text],input[type=tel],input[type=number],input[type=date],select,textarea{width:100%;padding:11px 12px;border:1.5px solid var(--line);border-radius:13px;background:#fafcfa;color:var(--tx);outline:0;transition:border .2s,box-shadow .2s}
input:focus,select:focus,textarea:focus{border-color:var(--g5);box-shadow:0 0 0 3px rgba(47,158,107,.15)}
.days{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}
.days label{position:relative}
.days input{position:absolute;opacity:0}
.days span{display:block;text-align:center;padding:9px 0;border-radius:11px;background:var(--bg);font-size:12px;border:1.5px solid transparent;transition:.2s;color:var(--tx)}
.days input:checked+span{background:var(--g8);color:#fff;transform:scale(1.05)}
.seg{display:flex;gap:6px;flex-wrap:wrap}
.seg label{position:relative}.seg input{position:absolute;opacity:0}
.seg span{display:block;padding:8px 14px;border-radius:12px;background:var(--bg);font-size:13.5px;transition:.2s;color:var(--tx)}
.seg input:checked+span{background:var(--g8);color:#fff}
.tabs{display:flex;background:#e8eee9;padding:4px;border-radius:14px;margin-bottom:12px}
.tabs button{flex:1;padding:8px;border-radius:11px;font-weight:700;color:var(--mut);transition:.25s}
.tabs button.on{background:#fff;color:var(--g8);box-shadow:var(--sh)}
.search{display:flex;align-items:center;gap:8px;background:#fff;border-radius:14px;padding:0 12px;margin-bottom:12px;box-shadow:var(--sh)}
.search input{border:0;box-shadow:none!important;background:none;padding:12px 0}
.empty{text-align:center;color:var(--mut);padding:34px 10px}
.empty svg{width:56px;height:56px;opacity:.35;stroke-width:1.4}
.toast{position:fixed;bottom:100px;left:50%;transform:translateX(-50%);background:var(--g9);color:#fff;padding:10px 18px;border-radius:14px;z-index:99;animation:enter .3s both;box-shadow:0 8px 20px rgba(0,0,0,.25);max-width:90%}
.ring{position:relative;width:88px;height:88px;flex:none}
.ring svg{transform:rotate(-90deg)}
.ring circle{fill:none;stroke-width:9;stroke-linecap:round}
.ring .bg{stroke:var(--line)}.ring .fg{stroke:url(#gr);transition:stroke-dashoffset 1.1s cubic-bezier(.2,.8,.2,1)}
.ring b{position:absolute;inset:0;display:grid;place-items:center;font-size:15px;color:var(--g8)}
.chart{display:flex;align-items:flex-end;gap:8px;height:120px;padding-top:6px}
.chart .col{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;font-size:11px;color:var(--mut)}
.chart .b{width:70%;border-radius:8px 8px 3px 3px;background:linear-gradient(180deg,var(--gold),var(--g5));height:0;transition:height .9s cubic-bezier(.2,.8,.2,1)}
.week{display:grid;grid-template-columns:repeat(7,1fr);gap:5px;text-align:center;font-size:11px}
.week div{background:var(--bg);border-radius:12px;padding:6px 2px;min-height:62px}
.week .today{background:var(--g8);color:#fff}
.week b{display:block;font-size:12px}
.hint{font-size:12.5px;color:var(--mut)}
.alert{display:flex;gap:10px;align-items:flex-start;padding:10px 12px;border-radius:14px;margin-bottom:8px;background:var(--amb1);color:#6d4a05;font-size:13.5px}
.alert.red{background:var(--red1);color:#8e2a20}.alert.ok{background:var(--g1);color:var(--g8)}
.kv{display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px dashed var(--line);font-size:14px}
.kv:last-child{border:0}
.mnav{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}
.rev{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:6px;margin-bottom:6px;align-items:center}
.sub-t{font-weight:800;color:var(--g8);margin:10px 0 6px}
.stars button{font-size:22px;color:#d4dad6;transition:.15s}.stars button.on{color:var(--gold);transform:scale(1.1)}
.pill{display:flex;justify-content:space-between;align-items:center;padding:8px 12px;background:var(--bg);border-radius:12px;margin-bottom:6px;font-size:13.5px}

.lg{width:38px;height:38px;border-radius:11px;box-shadow:0 2px 8px rgba(0,0,0,.25)}
.log{white-space:pre-wrap;font-size:13px;max-height:260px;overflow:auto;background:var(--bg);border-radius:12px;padding:10px;-webkit-user-select:text;user-select:text;line-height:1.8}
textarea{resize:none}

/* ===== ترابط + حصص ===== */
.tap{cursor:pointer;transition:transform .15s}.tap:active{transform:scale(.98)}
.stat[data-a],.col[data-a],.wn,.item[data-a]{cursor:pointer}
.stat[data-a]:active{transform:scale(.97)}
.wn{background:none!important;padding:2px 0!important;min-height:0!important;font-size:10.5px;text-decoration:underline;text-decoration-color:rgba(0,0,0,.2)}
.week .today .wn{text-decoration-color:rgba(255,255,255,.5)}
.lnk{color:var(--g7);cursor:pointer}
.col[data-a]:active .b{filter:brightness(1.15)}
.grid4{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px}
.mstat{background:#fff;border-radius:16px;padding:10px 4px;text-align:center;box-shadow:var(--sh);color:var(--g8)}
.mstat .ic{width:20px;height:20px;margin:0 auto}
.mstat b{display:block;font-size:20px;line-height:1.3}
.mstat span{font-size:11.5px;color:var(--mut)}
.mstat.ok{color:#1f8f4e}.mstat.bad{color:var(--red)}.mstat.gold{color:#a67c00}
.fchips{display:flex;gap:8px;overflow-x:auto;padding:2px 2px 8px;margin-bottom:4px;scrollbar-width:none}
.fchips::-webkit-scrollbar{display:none}
.fchips button{flex:none;display:flex;align-items:center;gap:6px;padding:7px 14px;border-radius:99px;background:#fff;box-shadow:var(--sh);font-size:13.5px;color:var(--tx);transition:.2s;white-space:nowrap}
.fchips.sm button{padding:5px 12px;font-size:12.5px;background:#e8eee9;box-shadow:none}
.fchips button.on{background:var(--g8);color:#fff}
.mini{display:inline-grid;place-items:center;width:22px;height:22px;border-radius:8px;background:var(--g1);color:var(--g8);font-size:12px;font-weight:800;margin-left:6px}
.fchips button.on .mini{background:rgba(255,255,255,.22);color:#fff}
.dhead{display:flex;align-items:center;gap:8px;font-weight:800;color:var(--g8);margin:14px 4px 8px;font-size:14px}
.dhead .ic{width:17px;height:17px}
.lcard{display:flex;gap:12px;background:#fff;border-radius:18px;box-shadow:var(--sh);padding:10px;margin-bottom:10px;position:relative;overflow:hidden;transition:transform .15s}
.lcard:active{transform:scale(.985)}
.lcard:before{content:"";position:absolute;right:0;top:0;bottom:0;width:4px;background:var(--g5)}
.lcard.bad:before{background:var(--red)}.lcard.warn:before{background:#e0a030}
.ldate{flex:none;width:54px;border-radius:14px;background:linear-gradient(160deg,var(--g8),var(--g7));color:#fff;text-align:center;padding:6px 0;line-height:1.25;align-self:flex-start}
.ldate b{display:block;font-size:21px}.ldate span{display:block;font-size:11.5px;opacity:.9}.ldate i{display:block;font-style:normal;font-size:11px;opacity:.75}
.lcard.bad .ldate{background:linear-gradient(160deg,#a93226,#d9594c)}.lcard.warn .ldate{background:linear-gradient(160deg,#a8741a,#d9a63a)}
.lbody{flex:1;min-width:0}
.lhead{display:flex;align-items:center;justify-content:space-between;gap:6px}
.lname{font-weight:800;display:flex;align-items:center}
.lstat{display:inline-flex;align-items:center;gap:4px;font-size:12.5px;padding:2px 9px;border-radius:99px;font-weight:700}
.lstat .ic{width:15px;height:15px}
.lstat.ok{background:#e1f5e9;color:#1f8f4e}.lstat.bad{background:var(--red1);color:var(--red)}.lstat.warn{background:var(--amb1);color:var(--amb)}
.lchips{margin:2px 0 4px}
.lrow{display:flex;align-items:center;gap:7px;padding:6px 9px;border-radius:11px;margin-top:5px;font-size:13.5px;background:var(--bg)}
.lrow .ic{width:17px;height:17px}
.lrow span{color:var(--mut);font-size:12px;flex:none}
.lrow b{font-weight:700;min-width:0}
.lrow small{font-weight:400;color:var(--mut)}
.lrow.new{background:#e9f6ee;color:var(--g8)}
.lrow.rev{background:#e8f1fa;color:var(--blue)}
.lrow.req{background:#fff4dc;color:#8a5d00}
.lrow.nt{background:#f3f0f8;color:#5b4a85}
.ic.tiny{width:13px;height:13px}

/* ===== الشاشة الافتتاحية ===== */
#splash{position:fixed;inset:0;z-index:999;display:flex;flex-direction:column;align-items:center;justify-content:center;
  background:radial-gradient(circle at 50% 35%,#177245 0%,#0b3d2e 62%,#07281e 100%);color:#fff;transition:opacity .6s ease,transform .6s ease}
#splash.out{opacity:0;transform:scale(1.04);pointer-events:none}
#splash .glow{position:absolute;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,rgba(201,162,39,.28),transparent 65%);animation:glow 2.4s ease-in-out infinite alternate}
@keyframes glow{from{transform:scale(.85);opacity:.6}to{transform:scale(1.1);opacity:1}}
#splash svg.lg{width:168px;height:168px;position:relative;animation:lpop .9s cubic-bezier(.2,1.3,.4,1) both;filter:drop-shadow(0 12px 30px rgba(0,0,0,.35))}
@keyframes lpop{from{transform:scale(.4) rotate(-12deg);opacity:0}to{transform:none;opacity:1}}
#splash .arch{stroke-dasharray:1200;stroke-dashoffset:1200;animation:draw 1.3s .25s ease-out forwards}
@keyframes draw{to{stroke-dashoffset:0}}
#splash .moon,#splash .star{opacity:0;animation:fadein .6s 1s ease-out forwards}
#splash .star{animation-delay:1.25s}
@keyframes fadein{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
#splash .bk{opacity:0;animation:rise .7s .55s cubic-bezier(.2,.9,.3,1) forwards}
@keyframes rise{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
#splash h1{position:relative;margin:22px 0 4px;font-size:26px;letter-spacing:.3px;animation:rise .8s 1.1s both}
#splash p{position:relative;margin:0;opacity:.8;font-size:14px;animation:rise .8s 1.3s both}
#splash .dots{position:relative;display:flex;gap:7px;margin-top:34px;animation:fadein .6s 1.5s both}
#splash .dots i{width:8px;height:8px;border-radius:50%;background:#e3c766;animation:dot 1s infinite ease-in-out}
#splash .dots i:nth-child(2){animation-delay:.15s}#splash .dots i:nth-child(3){animation-delay:.3s}
@keyframes dot{0%,100%{transform:translateY(0);opacity:.5}50%{transform:translateY(-7px);opacity:1}}

