/* ميراث الأنبياء – إدارة الأكاديمية */
"use strict";
const KEY="mirath_academy_v1",VER=4,DEFAULT_UPDATE_URL="https://raw.githubusercontent.com/aifreemontage-ctrl/mirath-app/main/bundle.json";
const DAYS=["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة","السبت"];
const MONTHS=["يناير","فبراير","مارس","أبريل","مايو","يونيو","يوليو","أغسطس","سبتمبر","أكتوبر","نوفمبر","ديسمبر"];
const STATUS={present:"حضر",absent:"غاب",excused:"اعتذر",makeup:"تعويض"};

/* ---------- أيقونات ---------- */
const P={
 home:'<path d="M3 10.5 12 3l9 7.5V21H3z"/><path d="M9.5 21v-6.5h5V21"/>',
 users:'<circle cx="9" cy="8" r="3.5"/><path d="M2.5 20c0-3.6 2.9-6 6.5-6s6.5 2.4 6.5 6"/><circle cx="17.5" cy="9" r="2.5"/><path d="M17 14.2c2.6.2 4.5 2.1 4.5 5.3"/>',
 book:'<path d="M12 6.5C10.5 5 8 4.5 4 4.5V19c4 0 6.5.6 8 2 1.5-1.4 4-2 8-2V4.5c-4 0-6.5.5-8 2z"/><path d="M12 6.5V21"/>',
 wallet:'<rect x="3" y="6" width="18" height="14" rx="3.5"/><path d="M3 10h18"/><circle cx="16.5" cy="14.5" r="1.2"/><path d="M6 6l9-3 1.5 3"/>',
 more:'<circle cx="5" cy="12" r="1.4"/><circle cx="12" cy="12" r="1.4"/><circle cx="19" cy="12" r="1.4"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 phone:'<path d="M5 4h3.5l2 5-2.4 1.5a11 11 0 0 0 5.4 5.4L15 13.5l5 2V19a2 2 0 0 1-2 2A15 15 0 0 1 3 6a2 2 0 0 1 2-2z"/>',
 wa:'<path d="M21 11.5a8.5 8.5 0 0 1-12.4 7.5L3 20.5l1.6-5.1A8.5 8.5 0 1 1 21 11.5z"/><path d="M9 8.5c.2 3 2.5 5.4 5.5 6l1.2-1.3-2-1-.8.8c-.8-.4-1.5-1.1-1.9-1.9l.8-.8-1-2z"/>',
 trash:'<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/>',
 edit:'<path d="M4 20h4L19 9l-4-4L4 16z"/><path d="M13.5 6.5l4 4"/>',
 check:'<path d="M5 12.5l4.5 4.5L19 7.5"/>',
 x:'<path d="M6 6l12 12M18 6L6 18"/>',
 archive:'<rect x="3" y="4" width="18" height="4" rx="1.5"/><path d="M5 8v11h14V8M10 12.5h4"/>',
 cal:'<rect x="3.5" y="5" width="17" height="15.5" rx="3"/><path d="M3.5 10h17M8 3v4M16 3v4"/>',
 search:'<circle cx="11" cy="11" r="6.5"/><path d="M20 20l-4.2-4.2"/>',
 warn:'<path d="M12 4l9.5 16.5h-19z"/><path d="M12 10v4.5M12 17.5v.2"/>',
 chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/>',
 back:'<path d="M9 5l7 7-7 7"/>',
 down:'<path d="M12 3v12M7 11l5 5 5-5M5 20h14"/>',
 up:'<path d="M12 16V4M7 8l5-5 5 5M5 20h14"/>',
