function seed(){return typeof makeSeed==="function"?makeSeed(uid,R,VER,DEFAULT_UPDATE_URL):{ver:VER,students:[],lessons:[],payments:[],expenses:[],settings:{prices:{4:200,8:250,12:300,16:350},cc:"20",academy:"أكاديمية ميراث الأنبياء",updateUrl:DEFAULT_UPDATE_URL}}}
function migrate(old){
  const n=seed();
  old.students.forEach(o=>{const m=n.students.find(s=>s.name===o.name);if(m){m.phone=o.phone||"";if(o.notes)m.notes=o.notes;if(o.archived){m.archived=true;m.archivedAt=o.archivedAt}}else n.students.push({base:null,log:"",...o})});
  const byName=id=>{const o=old.students.find(s=>s.id===id);return o&&n.students.find(s=>s.name===o.name)};
  old.lessons.forEach(l=>{const m=byName(l.sid);if(!m||n.lessons.some(x=>x.sid===m.id&&x.date===l.date))return;n.lessons.push({...l,sid:m.id})});
  const gone=new Set(["2026-10|250|pay|2026-11-04","2026-10|250|pay|2026-10-21","2026-11|200|pay|2026-11-18","2026-11|250|pay|2026-11-18","2026-11|50|disc|2026-11-04","2026-11|50|disc|2026-11-08"]);
  old.payments.forEach(p=>{if(gone.has(`${p.month}|${p.amount}|${p.kind}|${p.date}`))return;const m=byName(p.sid);if(!m||n.payments.some(x=>x.sid===m.id&&x.month===p.month&&+x.amount===+p.amount&&x.kind===p.kind&&x.date===p.date))return;n.payments.push({...p,sid:m.id})});
  n.expenses=(old.expenses||[]).filter(e=>e.date>="2026-11-01");
  const os=old.settings||{};n.settings={...n.settings,...os,prices:{...n.settings.prices,...(os.prices||{})}};
  n.ver=VER;return n}
let db=load();
function load(){let d=null;try{d=JSON.parse(localStorage.getItem(KEY))}catch(e){}
  if(!d||!d.students){d=seed();localStorage.setItem(KEY,JSON.stringify(d));return d}
  if((d.ver||1)<VER){snapshot(d,"قبل التحديث");d=migrate(d);localStorage.setItem(KEY,JSON.stringify(d))}return d}
let saveT=null;
function save(){localStorage.setItem(KEY,JSON.stringify(db));clearTimeout(saveT);saveT=setTimeout(()=>snapshot(db),1500)}
function snapshot(d,tag){try{const k="qa_snap_"+new Date().toISOString().slice(0,10)+(tag?"_"+tag:"");localStorage.setItem(k,JSON.stringify(d));const ks=Object.keys(localStorage).filter(x=>x.startsWith("qa_snap_")).sort();while(ks.length>10)localStorage.removeItem(ks.shift())}catch(e){}}
try{navigator.storage&&navigator.storage.persist&&navigator.storage.persist()}catch(e){}

