const $=s=>document.querySelector(s);
const esc=t=>String(t??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const pad=n=>String(n).padStart(2,"0");
const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const today=()=>iso(new Date());
const pd=s=>{const[y,m,d]=s.split("-").map(Number);return new Date(y,m-1,d,12)};
const dname=s=>DAYS[pd(s).getDay()];
const nice=s=>{const d=pd(s);return `${DAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`};
const mkey=s=>s.slice(0,7);
const mlabel=k=>{const[y,m]=k.split("-").map(Number);return `${MONTHS[m-1]} ${y}`};
const addM=(k,n)=>{let[y,m]=k.split("-").map(Number);m+=n;while(m>12){m-=12;y++}while(m<1){m+=12;y--}return `${y}-${pad(m)}`};
const money=n=>`${Math.round(n).toLocaleString("en-US")} ج`;
const sOf=id=>db.students.find(x=>x.id===id);
const active=()=>db.students.filter(s=>!s.archived);
function toast(t){const e=document.createElement("div");e.className="toast";e.textContent=t;document.body.appendChild(e);setTimeout(()=>e.remove(),2400)}
function cnt(){document.querySelectorAll("[data-count]").forEach(el=>{const to=+el.dataset.count,sfx=el.dataset.sfx||"",t0=performance.now();const f=t=>{const p=Math.min(1,(t-t0)/800),e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e).toLocaleString("en-US")+sfx;if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)})}
function bars(){requestAnimationFrame(()=>requestAnimationFrame(()=>{document.querySelectorAll("[data-w]").forEach(e=>e.style.width=e.dataset.w+"%");document.querySelectorAll("[data-h]").forEach(e=>e.style.height=e.dataset.h+"%");document.querySelectorAll("[data-off]").forEach(e=>e.style.strokeDashoffset=e.dataset.off)}))}

/* ---------- منطق الطلبة والحصص ---------- */
const cycle=s=>+s.sessions||(s.days.length*4)||4;
const priceOf=s=>{if(s.price!==""&&s.price!=null&&!isNaN(+s.price))return +s.price;const p=db.settings.prices,n=cycle(s);return p[n]!=null?+p[n]:Math.round(n/4*(+p[4]||200))};
const counted=l=>l.status==="present"||l.status==="makeup";
const cycOf=l=>l.cyc||mkey(l.date);
function curCyc(sid){const s=sOf(sid),L=lessonsOf(sid).filter(counted);if(!L.length)return mkey((s&&s.start)||today());const last=L[L.length-1];return(+last.no>=cycle(s))?addM(cycOf(last),1):cycOf(last)}
const cycCount=(sid,c)=>lessonsOf(sid).filter(l=>counted(l)&&cycOf(l)===c).length;
const lessonsOf=id=>db.lessons.filter(l=>l.sid===id).sort((a,b)=>a.date===b.date?(a.ts||0)-(b.ts||0):a.date<b.date?-1:1);
function nextNo(id){const s=sOf(id);const L=lessonsOf(id).filter(counted);if(!L.length)return 1;const n=+L[L.length-1].no||0;return n>=cycle(s)?1:n+1}
function progressOf(s){const m={};lessonsOf(s.id).filter(l=>counted(l)&&l.neu).forEach(l=>(m[l.neu.s]=m[l.neu.s]||[]).push([l.neu.f,l.neu.t]));let tot=0;for(const k in m){const a=m[k].sort((x,y)=>x[0]-y[0]);let c=null;for(const r of a){if(!c)c=[...r];else if(r[0]<=c[1]+1)c[1]=Math.max(c[1],r[1]);else{tot+=c[1]-c[0]+1;c=[...r]}}if(c)tot+=c[1]-c[0]+1}return Math.min(TOTAL_AYAHS,tot+(+s.prev||0))}
const nextOf=x=>{if(!x)return null;const am=SURAHS[x.s][1];return x.t<am?{s:x.s,f:x.t+1}:(x.s<113?{s:x.s+1,f:1}:null)};
function suggest(id){const s=sOf(id),L=lessonsOf(id).filter(counted);let neu=null,rev=null,req=null;
  for(let i=L.length-1;i>=0;i--){if(!neu&&L[i].neu)neu=L[i].neu;if(!rev&&L[i].rev&&L[i].rev.length)rev=L[i].rev[L[i].rev.length-1];if(!req&&(L[i].reqNew||L[i].reqRev))req={n:L[i].reqNew,r:L[i].reqRev};if(neu&&rev&&req)break}
  if(!neu&&s.base)neu=s.base.neu;if(!rev&&s.base)rev=s.base.rev;
  return{n:nextOf(neu),r:nextOf(rev),lastNew:neu,lastRev:rev,req}}
const range=x=>x?`${SURAHS[x.s][0]} ${x.f}${x.t&&x.t!==x.f?" - "+x.t:""}`:"—";
/* الفلوس: السعر − الخصم = المطلوب، والمدفوع بيتحسب من الدفعات النقدية */
const sumP=(sid,m,k)=>db.payments.filter(p=>p.sid===sid&&p.month===m&&p.kind===k).reduce((a,p)=>a+(+p.amount||0),0);
const cashOf=(sid,m)=>sumP(sid,m,"pay"),discOf=(sid,m)=>sumP(sid,m,"disc");
const priceIn=(s,m)=>{if(s.start&&mkey(s.start)>m)return 0;if(m<"2026-11"&&s.priceHist)return +s.priceHist[m]||0;if(s.archived&&s.archivedAt&&mkey(s.archivedAt)<m)return 0;return priceOf(s)};
const needOf=(s,m)=>Math.max(0,priceIn(s,m)-discOf(s.id,m));
const leftOf=(s,m)=>Math.max(0,needOf(s,m)-cashOf(s.id,m));
function monthStats(m){let exp=0,got=0,left=0;db.students.filter(s=>!s.archived||cashOf(s.id,m)>0).forEach(s=>{exp+=needOf(s,m);got+=cashOf(s.id,m);left+=leftOf(s,m)});
  const ex=db.expenses.filter(e=>mkey(e.date)===m).reduce((a,e)=>a+(+e.amount||0),0);return{exp,got,left,cash:got,ex}}
function waNum(p){let d=String(p||"").replace(/[^\d]/g,"");if(d.startsWith("00"))d=d.slice(2);else if(d.startsWith("0"))d=db.settings.cc+d.slice(1);return d}
function contactBtns(s){if(!s.phone)return"";const n=waNum(s.phone);return`<a class="ibtn call" href="tel:+${n}" onclick="event.stopPropagation()" title="اتصال">${ic("phone")}</a><a class="ibtn wa" href="https://wa.me/${n}" onclick="event.stopPropagation()" title="واتساب">${ic("wa")}</a>`}
function moneyLine(s,m){const p=priceIn(s,m),d=discOf(s.id,m);return d?`${money(p)} − خصم ${money(d)} = ${money(p-d)}`:money(p)}

