/* ---------- الرئيسية ---------- */
function vHome(){
  const m=mkey(today()),ms=monthStats(m),act=active(),td=new Date().getDay();
  const sched=act.filter(s=>s.days.includes(td));
  const done=id=>db.lessons.some(l=>l.sid===id&&l.date===today());
  const al=[];
  act.forEach(s=>{
    const cm=curCyc(s.id),left=leftOf(s,cm),L=lessonsOf(s.id).filter(counted),done=L.length&&+L[L.length-1].no>=cycle(s);
    if(left>0)al.push(`<div class="alert ${done?"":"red"} tap" data-a="open" data-v="${s.id}">${ic(done?"warn":"coin")}<div><b>${esc(s.name)}</b> – ${done?"خلّص دورته، وقت التجديد: ":""}لسه عليه ${money(left)} من اشتراك شهر ${MONTHS[+cm.slice(5)-1]}</div></div>`);
    const all=lessonsOf(s.id);if(all.length){const d=Math.floor((new Date()-pd(all[all.length-1].date))/864e5);if(d>=14)al.push(`<div class="alert tap" data-a="open" data-v="${s.id}">${ic("cal")}<div><b>${esc(s.name)}</b> مسجّلتلوش حصة من ${d} يوم</div></div>`)}
  });
  const six=[];for(let i=5;i>=0;i--)six.push(addM(m,-i));const vals=six.map(k=>monthStats(k).cash),mx=Math.max(1,...vals);
  const week=DAYS.map((d,i)=>{const n=act.filter(s=>s.days.includes(i));return`<div class="${i===td?"today":""}"><b>${d.replace("ال","")}</b>${n.length?n.map(x=>`<div class="wn" data-a="open" data-v="${x.id}">${esc(x.name)}</div>`).join(""):"<span style='opacity:.4'>—</span>"}</div>`}).join("");
  const upd=window.__pendingApk?`<div class="alert tap" style="background:#fff4dc" data-a="installApk">${ic("refresh")}<div><b>فيه نسخة جديدة من التطبيق</b> – دوس هنا عشان تحدّثه (نسخة ${window.__pendingApk.ver})</div></div>`:"";
  return`${upd}
  <div class="grid2 stagger" style="margin-bottom:12px">
    <div class="stat s1" style="--i:0" data-a="goto" data-v="students">${ic("users")}<div class="n" data-count="${act.length}">0</div><div class="l">طالب شغّال</div></div>
    <div class="stat s3" style="--i:1" data-a="goto" data-v="lessons">${ic("book")}<div class="n" data-count="${sched.length}">0</div><div class="l">حصص النهارده</div></div>
    <div class="stat s2" style="--i:2" data-a="goto" data-v="fin">${ic("wallet")}<div class="n" data-count="${ms.got}" data-sfx=" ج">0</div><div class="l">اللي اتحصّل الشهر ده</div></div>
    <div class="stat s4" style="--i:3" data-a="goto" data-v="fin">${ic("coin")}<div class="n" data-count="${ms.left}" data-sfx=" ج">0</div><div class="l">لسه باقي الشهر ده</div></div>
  </div>
  <div class="card"><h3>${ic("cal")} جدول النهارده – ${DAYS[td]}</h3>
  ${sched.length?sched.map(s=>`<div class="item" style="box-shadow:none;background:var(--bg)" data-a="lessonFor" data-v="${s.id}"><div class="ava">${esc(s.name[0])}</div><div class="sp"><div class="t">${esc(s.name)}</div><div class="m">الحصة الجاية رقم ${nextNo(s.id)} من ${cycle(s)}</div></div>${done(s.id)?`<span class="chip">✓ اتسجّلت</span>`:`<span class="btn sm">سجّل</span>`}</div>`).join(""):`<div class="hint">مفيش حصص النهارده.</div>`}</div>
  <div class="card"><h3>${ic("warn")} تنبيهات</h3>${al.length?al.join(""):`<div class="alert ok">${ic("check")}<div>كله تمام، مفيش تنبيهات.</div></div>`}</div>
  <div class="card"><h3>${ic("chart")} اللي اتحصّل آخر 6 شهور</h3><div class="chart">${six.map((k,i)=>`<div class="col" data-a="finMonth" data-v="${k}"><span>${vals[i]?Math.round(vals[i]):""}</span><div class="b" data-h="${Math.max(3,vals[i]/mx*85)}"></div><span>${MONTHS[+k.slice(5)-1]}</span></div>`).join("")}</div></div>
  <div class="card"><h3>${ic("cal")} جدول الأسبوع</h3><div class="week">${week}</div></div>`;
}

