function vStudent(s){
  const L=lessonsOf(s.id),pr=progressOf(s),sg=suggest(s.id),m=mkey(today());
  const att={p:L.filter(counted).length,a:L.filter(l=>l.status==="absent").length,e:L.filter(l=>l.status==="excused").length};
  const pct=pr/TOTAL_AYAHS,C=2*Math.PI*36,pays=db.payments.filter(p=>p.sid===s.id).sort((a,b)=>a.date<b.date?1:-1).slice(0,6);
  const price=priceIn(s,m),disc=discOf(s.id,m),cash=cashOf(s.id,m),need=needOf(s,m),left=leftOf(s,m);
  return`
  <div class="card"><div class="row"><div class="ava" style="width:54px;height:54px;font-size:22px">${esc(s.name[0])}</div><div class="sp"><div class="t" style="font-weight:800;font-size:17px">${esc(s.name)}</div><div class="m hint">${s.phone?esc(s.phone):"مفيش رقم موبايل"}</div></div>${contactBtns(s)}</div>
  <div style="margin-top:8px">${s.days.map(d=>`<span class="chip">${DAYS[d]}</span>`).join("")}<span class="chip gold">${cycle(s)} حصص في الشهر</span><span class="chip blue">${money(priceOf(s))}</span></div>
  ${s.notes?`<div class="hint" style="margin-top:6px">${esc(s.notes)}</div>`:""}
