function lessonRow(l,showName){
  const s=sOf(l.sid),st=l.status,d=pd(l.date),ok=counted(l),sum=x=>x?(x.t-x.f+1):0;
  const si={present:["okc","ok"],makeup:["refresh","ok"],absent:["xc","bad"],excused:["clock","warn"]}[st];
  const rr=(cls,icn,lab,txt)=>`<div class="lrow ${cls}">${ic(icn)}${lab?`<span>${lab}</span>`:""}<b>${txt}</b></div>`;
  return`<div class="lcard ${si[1]}" data-a="editLesson" data-v="${l.id}">
  <div class="ldate"><b>${d.getDate()}</b><span>${MONTHS[d.getMonth()]}</span><i>${DAYS[d.getDay()].replace("ال","")}</i></div>
  <div class="lbody">
    <div class="lhead">${showName&&s?`<span class="lname lnk" data-a="open" data-v="${l.sid}"><span class="mini">${esc(s.name[0])}</span>${esc(s.name)}</span>`:`<span class="lname">حصة ${ok&&l.no?l.no:""}</span>`}<span class="lstat ${si[1]}">${ic(si[0])} ${STATUS[st]}</span></div>
    <div class="lchips">${ok&&l.no&&showName?`<span class="chip gold">حصة ${l.no}</span>`:""}<span class="chip blue">دورة ${MONTHS[+cycOf(l).slice(5)-1]}</span>${l.grade?`<span class="chip gold">${"★".repeat(l.grade)}</span>`:""}</div>
    ${l.neu?rr("new","book","جديد",range(l.neu)+` <small>(${sum(l.neu)} آية)</small>`):""}
    ${(l.rev||[]).map(r=>rr("rev","refresh","مراجعة",range(r))).join("")}
    ${l.reqNew||l.reqRev?rr("req","flag","المطلوب",(l.reqNew?range(l.reqNew):"")+(l.reqNew&&l.reqRev?" + ":"")+esc(l.reqRev||"")):""}
    ${l.note?rr("nt","note","",esc(l.note)):""}
  </div></div>`}

/* ---------- الحصص ---------- */
function vLessons(){
  let L=db.lessons.slice();if(route.lsid)L=L.filter(l=>l.sid===route.lsid);if(route.lm)L=L.filter(l=>mkey(l.date)===route.lm);
  L.sort((x,y)=>x.date===y.date?(y.ts||0)-(x.ts||0):x.date<y.date?1:-1);
  const months=[...new Set(db.lessons.map(l=>mkey(l.date)))].sort().reverse();
  const att=L.filter(counted).length,abs=L.filter(l=>l.status==="absent"||l.status==="excused").length,ay=L.filter(l=>counted(l)&&l.neu).reduce((t,l)=>t+(l.neu.t-l.neu.f+1),0);
  let last="",h="";L.forEach(l=>{if(l.date!==last){last=l.date;h+=`<div class="dhead">${ic("cal")} ${nice(l.date)}</div>`}h+=lessonRow(l,true)});
  return`<div class="grid4 stagger">
    <div class="mstat" style="--i:0">${ic("book")}<b data-count="${L.length}">0</b><span>حصة</span></div>
    <div class="mstat ok" style="--i:1">${ic("okc")}<b data-count="${att}">0</b><span>حضور</span></div>
    <div class="mstat bad" style="--i:2">${ic("xc")}<b data-count="${abs}">0</b><span>غياب</span></div>
    <div class="mstat gold" style="--i:3">${ic("star")}<b data-count="${ay}">0</b><span>آية جديدة</span></div></div>
  <div class="fchips"><button class="${!route.lsid?"on":""}" data-a="lsidc" data-v="">الكل</button>${db.students.map(s=>`<button class="${route.lsid===s.id?"on":""}" data-a="lsidc" data-v="${s.id}"><span class="mini">${esc(s.name[0])}</span>${esc(s.name)}</button>`).join("")}</div>
  <div class="fchips sm"><button class="${!route.lm?"on":""}" data-a="lmc" data-v="">كل الشهور</button>${months.map(k=>`<button class="${route.lm===k?"on":""}" data-a="lmc" data-v="${k}">${mlabel(k)}</button>`).join("")}</div>
  ${h?`<div class="stagger">${h}</div>`:`<div class="empty">${ic("book")}<div>مفيش حصص متسجّلة</div><button class="btn" style="margin-top:12px" data-a="addLesson">سجّل أول حصة</button></div>`}`}

