  <div class="grid2 stagger" style="margin-bottom:12px"><div class="stat s3" style="--i:0"><div class="n" data-count="${ms.exp}" data-sfx=" ج">0</div><div class="l">المطلوب (بعد الخصم)</div></div><div class="stat s1" style="--i:1"><div class="n" data-count="${ms.got}" data-sfx=" ج">0</div><div class="l">اللي اتدفع</div></div><div class="stat s4" style="--i:2"><div class="n" data-count="${ms.left}" data-sfx=" ج">0</div><div class="l">لسه باقي</div></div><div class="stat s2" style="--i:3"><div class="n" data-count="${ms.got-ms.ex}" data-sfx=" ج">0</div><div class="l">الصافي بعد المصاريف</div></div></div>
  <div class="card"><h3>${ic("users")} اشتراكات الطلبة</h3>${st.length?st.map(s=>{const need=needOf(s,m),p=cashOf(s.id,m),r=leftOf(s,m);return`<div class="item" style="box-shadow:none;background:var(--bg)" data-a="open" data-v="${s.id}"><div class="ava">${esc(s.name[0])}</div><div class="sp"><div class="t">${esc(s.name)}</div><div class="m">${moneyLine(s,m)} مطلوب</div><div class="m">اتدفع ${money(p)}${r>0?" · باقي "+money(r):""}</div><div class="bar"><i data-w="${need?Math.min(100,p/need*100):100}"></i></div></div>${r<=0?`<span class="chip">✓ خالص</span>`:`<button class="btn sm" data-a="addPay" data-v="${s.id}">دفعة</button>`}</div>`}).join(""):`<div class="hint">مفيش اشتراكات في الشهر ده.</div>`}</div>
  <div class="card"><h3>${ic("coin")} الدفعات والخصومات</h3>${pays.length?pays.map(p=>{const s=sOf(p.sid);return`<div class="pill"><span><b class="lnk" data-a="open" data-v="${p.sid}">${esc(s?s.name:"؟")}</b> · ${nice(p.date)}${p.kind==="disc"?" <span class='chip amb'>خصم</span>":""}${p.note?" – "+esc(p.note):""}</span><span class="row"><b>${p.kind==="disc"?"− ":""}${money(p.amount)}</b><button class="ibtn red" style="width:30px;height:30px" data-a="delPay" data-v="${p.id}">${ic("trash")}</button></span></div>`}).join(""):`<div class="hint">مفيش دفعات.</div>`}</div>
  <div class="card"><h3>${ic("down")} المصاريف <button class="btn sm sec" style="margin-right:auto" data-a="addExp">${ic("plus")} ضيف</button></h3>${exs.length?exs.map(e=>`<div class="pill"><span>${esc(e.title)} · ${nice(e.date)}</span><span class="row"><b>${money(e.amount)}</b><button class="ibtn red" style="width:30px;height:30px" data-a="delExp" data-v="${e.id}">${ic("trash")}</button></span></div>`).join(""):`<div class="hint">مفيش مصاريف.</div>`}</div>`}

