/* ---------- النماذج ---------- */
function modal(title,body,onSub,okText="احفظ"){
  const h=$("#modalhost");
  h.innerHTML=`<div class="overlay"><div class="sheet"><h2>${title}</h2><form id="mf">${body}<div class="row" style="margin-top:6px"><button class="btn sp" type="submit">${ic("check")} ${okText}</button><button class="btn sec" type="button" data-a="close">إلغاء</button></div></form></div></div>`;
  $("#mf").addEventListener("submit",e=>{e.preventDefault();const r=onSub(new FormData(e.target),e.target);if(r!==false)closeModal()});
  h.querySelector(".overlay").addEventListener("click",e=>{if(e.target.classList.contains("overlay"))closeModal()});
  return h}
function closeModal(){$("#modalhost").innerHTML=""}
const opt=(arr,sel)=>arr.map(([v,l])=>`<option value="${v}" ${String(sel)===String(v)?"selected":""}>${esc(l)}</option>`).join("");
const surahOpts=sel=>SURAHS.map((s,i)=>`<option value="${i}" ${sel===i?"selected":""}>${i+1}. ${s[0]}</option>`).join("");

