  <div class="f"><span class="hint">الأيام اللي بيجي فيها في الأسبوع</span><div class="days">${DAYS.map((d,i)=>`<label><input type="checkbox" name="day" value="${i}" ${e.days.includes(i)?"checked":""}><span>${d.replace("ال","")}</span></label>`).join("")}</div></div>
  <div class="grid2"><label class="f"><span>حصص الشهر (فاضي = الأيام × 4)</span><input type="number" name="sessions" inputmode="numeric" value="${e.sessions&&e.sessions!==e.days.length*4?e.sessions:""}"></label>
