  <div class="grid2"><label class="f"><span>بدأ إمتى</span><input type="date" name="start" value="${e.start||today()}"></label>
  <label class="f"><span>محفوظ قبل كده (آيات تقريبًا)</span><input type="number" name="prev" inputmode="numeric" value="${e.prev||0}"></label></div>
  <label class="f"><span>ملاحظات</span><textarea name="notes" rows="2">${esc(e.notes)}</textarea></label>`,
