    const o={name:f.get("name").trim(),phone:f.get("phone").trim(),days,sessions:+f.get("sessions")||days.length*4,price:f.get("price"),start:f.get("start"),prev:+f.get("prev")||0,notes:f.get("notes").trim()};
    if(s)Object.assign(s,o);else db.students.push({id:uid(),archived:false,base:null,log:"",...o});save();toast(s?"اتحدّث":"اتضاف الطالب");render()});
}

function lessonForm(sid,les){
  const act=active();if(!act.length&&!les){toast("ضيف طالب الأول");return}
