  const rowRev=r=>`<div class="rev" data-rev><select name="rs" data-role="sur">${surahOpts(r?r.s:0)}</select><input type="number" name="rf" inputmode="numeric" placeholder="من" min="1" value="${r?r.f:""}"><input type="number" name="rt" inputmode="numeric" placeholder="إلى" min="1" value="${r?r.t:""}"><button type="button" class="ibtn red" data-a="rmRev">${ic("x")}</button></div>`;
  const h=modal(les?"عدّل الحصة":"سجّل حصة",`
  <label class="f"><span>الطالب</span><select name="sid" id="lsid" ${les?"disabled":""}>${opt(db.students.filter(s=>!s.archived||s.id===sel).map(s=>[s.id,s.name]),sel)}</select></label>
