  <div class="f"><span class="hint" id="dn">${dname(base.date)}</span><div class="seg">${Object.entries(STATUS).map(([k,v])=>`<label><input type="radio" name="status" value="${k}" ${base.status===k?"checked":""}><span>${v}</span></label>`).join("")}</div></div>
