  <div class="sub-t">التسميع الجديد</div>
  <div class="rev" style="grid-template-columns:2fr 1fr 1fr"><select name="ns" data-role="sur" id="nsur"><option value="">— من غير —</option>${surahOpts(neu?neu.s:-1)}</select><input type="number" name="nf" id="nf" inputmode="numeric" placeholder="من" min="1" value="${neu?neu.f:""}"><input type="number" name="nt" id="nt" inputmode="numeric" placeholder="إلى" min="1" value="${neu?neu.t:""}"></div>
  <div class="hint" id="sugn">${sg.n?`المقترح: ${SURAHS[sg.n.s][0]} من آية ${sg.n.f}`:""}</div>
  <div class="sub-t">المراجعة</div><div id="revs">${(base.rev&&base.rev.length?base.rev:(!les&&sg.r?[{s:sg.r.s,f:sg.r.f,t:Math.min(SURAHS[sg.r.s][1],sg.r.f+14)}]:[])).map(rowRev).join("")}</div>
  <button type="button" class="btn sm sec" data-a="addRev">${ic("plus")} ضيف مراجعة</button>
  <div class="sub-t">المطلوب في الحصة الجاية</div>
  <div class="rev" style="grid-template-columns:2fr 1fr 1fr"><select name="qs" data-role="sur"><option value="">— جديد: من غير —</option>${surahOpts(rn?rn.s:-1)}</select><input type="number" name="qf" inputmode="numeric" placeholder="من" min="1" value="${rn?rn.f:""}"><input type="number" name="qt" inputmode="numeric" placeholder="إلى" min="1" value="${rn?rn.t:""}"></div>
  <label class="f"><span>مراجعة مطلوبة (كتابة حرة)</span><input type="text" name="qrev" placeholder="مثال: سور البروج والانشقاق" value="${esc(base.reqRev||"")}"></label>
  <div class="sub-t">تقييم الحصة</div><div class="stars" id="stars">${[1,2,3,4,5].map(i=>`<button type="button" data-a="star" data-v="${i}" class="${base.grade>=i?"on":""}">★</button>`).join("")}</div><input type="hidden" name="grade" id="grade" value="${base.grade||0}">
  </div>
  <label class="f" style="margin-top:10px"><span>ملاحظات</span><textarea name="note" rows="2">${esc(base.note)}</textarea></label>
  ${les?`<button type="button" class="btn red block" style="margin-bottom:10px" data-a="delLesson" data-v="${les.id}">${ic("trash")} امسح الحصة</button>`:""}`,
  f=>{
    const sidv=les?les.sid:f.get("sid"),status=f.get("status");
    const rng=(s,a,b)=>{s=+s;a=+a;b=+b||a;if(!a||a<1||b<a||b>SURAHS[s][1]){toast(`راجع آيات ${SURAHS[s][0]} (من 1 لـ ${SURAHS[s][1]})`);return null}return{s,f:a,t:b}};
    let n=null,rv=[],qn=null;
    if(status==="present"||status==="makeup"){
      if(f.get("ns")!==""){n=rng(f.get("ns"),f.get("nf"),f.get("nt"));if(!n)return false}
      const rs=f.getAll("rs"),rf=f.getAll("rf"),rt=f.getAll("rt");for(let i=0;i<rs.length;i++){if(!rf[i])continue;const r=rng(rs[i],rf[i],rt[i]);if(!r)return false;rv.push(r)}
      if(f.get("qs")!==""){qn=rng(f.get("qs"),f.get("qf"),f.get("qt"));if(!qn)return false}}
    const o={sid:sidv,date:f.get("date"),status,no:counted({status})?(+f.get("no")||nextNo(sidv)):null,neu:n,rev:rv,reqNew:qn,reqRev:(status==="present"||status==="makeup")?f.get("qrev").trim():"",note:f.get("note").trim(),grade:+f.get("grade")||0};
    if(les)Object.assign(les,o);else db.lessons.push({id:uid(),ts:Date.now(),cyc:curCyc(sidv),...o});save();toast("اتحفظت الحصة");render()});
  const sync=()=>{const st=h.querySelector("[name=status]:checked").value;$("#lbody").style.display=(st==="present"||st==="makeup")?"":"none"};
  h.addEventListener("change",e=>{if(e.target.name==="status")sync();if(e.target.id==="ldate")$("#dn").textContent=dname(e.target.value);
    if(e.target.id==="lsid"){$("#lno").value=nextNo(e.target.value);const g=suggest(e.target.value);if(g.n){$("#nsur").value=g.n.s;$("#nf").value=g.n.f;$("#nt").value=Math.min(SURAHS[g.n.s][1],g.n.f+9);$("#sugn").textContent=`المقترح: ${SURAHS[g.n.s][0]} من آية ${g.n.f}`}}
    if(e.target.dataset.role==="sur"){e.target.parentElement.querySelectorAll("input[type=number]").forEach(i=>i.max=SURAHS[+e.target.value||0][1])}});
  sync();
}

function payForm(sid){
