  const left=()=>{const s=sOf($("#psid").value);return s?leftOf(s,$("#pm").value):0};
  const h=modal("سجّل دفعة أو خصم",`
  <label class="f"><span>الطالب</span><select name="sid" id="psid">${opt(db.students.filter(s=>!s.archived||s.id===sid).map(s=>[s.id,s.name]),first)}</select></label>
  <div class="grid2"><label class="f"><span>عن شهر</span><input type="month" name="month" id="pm" value="${m}"></label><label class="f"><span>التاريخ</span><input type="date" name="date" value="${today()}"></label></div>
  <div class="f"><div class="seg"><label><input type="radio" name="kind" value="pay" checked><span>دفعة فلوس</span></label><label><input type="radio" name="kind" value="disc"><span>خصم من الاشتراك</span></label></div></div>
  <label class="f"><span id="plab">المبلغ (ج)</span><input type="number" name="amount" id="pa" inputmode="numeric" required></label>
  <div class="hint" id="pinfo"></div>
  <label class="f" style="margin-top:8px"><span>ملحوظة</span><input type="text" name="note" placeholder="مثال: مقدمًا"></label>`,
  f=>{const a=+f.get("amount");if(!a||a<=0){toast("اكتب مبلغ صح");return false}db.payments.push({id:uid(),sid:f.get("sid"),month:f.get("month"),amount:a,kind:f.get("kind"),date:f.get("date"),note:f.get("note").trim()});save();toast(f.get("kind")==="disc"?"اتسجّل الخصم":"اتسجّلت الدفعة");render()});
  const up=()=>{const s=sOf($("#psid").value),mm=$("#pm").value;if(!s)return;const k=h.querySelector("[name=kind]:checked").value;$("#pinfo").textContent="الاشتراك: "+moneyLine(s,mm)+" · اتدفع "+money(cashOf(s.id,mm))+" · الباقي "+money(leftOf(s,mm));$("#pa").value=k==="pay"?(left()||""):"";$("#plab").textContent=k==="pay"?"المبلغ المدفوع (ج)":"قيمة الخصم (ج)"};up();
  h.addEventListener("change",e=>{if(e.target.id==="psid"||e.target.id==="pm"||e.target.name==="kind")up()});
}
function expForm(){modal("مصروف جديد",`<label class="f"><span>البيان</span><input type="text" name="title" required placeholder="إيجار، أدوات، ..."></label><div class="grid2"><label class="f"><span>المبلغ</span><input type="number" name="amount" inputmode="numeric" required></label><label class="f"><span>التاريخ</span><input type="date" name="date" value="${today()}"></label></div>`,f=>{db.expenses.push({id:uid(),title:f.get("title").trim(),amount:+f.get("amount"),date:f.get("date")});save();toast("اتضاف");render()})}

/* ---------- نسخ احتياطي وتحديث ---------- */
async function exportData(){
  const json=JSON.stringify(db,null,1),name=`mirath-backup-${today()}.json`;
  try{const C=window.Capacitor;if(C&&C.Plugins&&C.Plugins.Filesystem&&C.Plugins.Share){const r=await C.Plugins.Filesystem.writeFile({path:name,data:json,directory:"CACHE",encoding:"utf8"});await C.Plugins.Share.share({title:name,url:r.uri,dialogTitle:"احفظ النسخة الاحتياطية"});return}}catch(e){}
  modal("نسخة احتياطية",`<div class="hint" style="margin-bottom:8px">انسخ الكلام ده كله وابعته لنفسك في ملاحظات (أو أي مكان). تقدر ترجّعه بعدين من زرار «استيراد».</div><textarea id="bk" rows="8" readonly style="direction:ltr">${esc(json)}</textarea>`,()=>{const t=$("#bk");t.select();try{document.execCommand("copy");toast("اتنسخ")}catch(e){}return false},"انسخ")}
const NU={
  async code(){try{const C=window.Capacitor;if(C&&C.nativePromise){const r=await C.nativePromise("Updater","versionCode",{});return +r.code}}catch(e){}return null},
  async install(apk){
    const C=window.Capacitor;toast("بنزّل التحديث...");
    try{const r=await C.nativePromise("Updater","install",{url:apk.url,sha256:apk.sha256});
      toast(r.state==="needperm"?"اسمح للتطبيق بتثبيت التحديثات من الشاشة اللي فتحت، وارجع دوس «حدّث التطبيق» تاني":"افتح شاشة التثبيت ودوس «تحديث»")}
    catch(e){const m=String((e&&e.message)||e);toast(m.includes("badhash")?"ملف التحديث مش سليم، جرّب بعدين":"حصلت مشكلة في التحديث، جرّب بعدين")}}
};
window.__pendingApk=null;
function banner(html){const t=document.createElement("div");t.className="toast";t.style.cssText+=";display:flex;align-items:center;gap:8px";t.innerHTML=html;document.body.appendChild(t);setTimeout(()=>t.remove(),12000);return t}
async function checkUpdate(manual){
  const url=(db.settings.updateUrl||DEFAULT_UPDATE_URL||"").trim();
  if(!url){if(manual)toast("اكتب رابط التحديثات الأول");return}
  try{const r=await fetch(url+(url.includes("?")?"&":"?")+"t="+Date.now(),{cache:"no-store"});if(!r.ok)throw 0;const b=await r.json();let found=false;
    const vc=await NU.code();
    if(b&&b.apk&&vc!=null&&b.apk.ver>vc){found=true;window.__pendingApk=b.apk;if(route.tab==="home"&&!$("#modalhost").firstChild)render();
      const t=banner(`فيه نسخة جديدة من التطبيق <button class="btn sm gold">حدّث التطبيق</button>`);t.querySelector("button").onclick=()=>{t.remove();NU.install(b.apk)}}
    else if(b&&b.ver>(window.APP_VER||VER)&&b.files){found=true;localStorage.setItem("qa_bundle",JSON.stringify(b));
      const t=banner(`فيه تحديث جديد اتحمّل <button class="btn sm gold">حدّث دلوقتي</button>`);t.querySelector("button").onclick=()=>location.reload()}
    else if(b&&b.apk&&vc==null&&manual)toast("أداة تحديث التطبيق مش متاحة في النسخة دي، ثبّت النسخة من الفولدر مرة");
    if(!found&&manual&&!(b&&b.apk&&vc==null))toast("إنت على آخر إصدار ✓")}catch(e){if(manual)toast("مقدرتش أوصل للتحديثات، اتأكد من النت والرابط")}}

/* ---------- الأحداث ---------- */
document.addEventListener("click",e=>{
  const b=e.target.closest(".btn,.fab,.ibtn");if(b&&!b.querySelector(".ripple")){const r=b.getBoundingClientRect(),d=Math.max(r.width,r.height),s=document.createElement("span");s.className="ripple";s.style.cssText=`width:${d}px;height:${d}px;left:${e.clientX-r.left-d/2}px;top:${e.clientY-r.top-d/2}px`;if(getComputedStyle(b).position==="static")b.style.position="relative";b.appendChild(s);setTimeout(()=>s.remove(),600)}
  const t=e.target.closest("[data-a]");if(!t)return;const a=t.dataset.a,v=t.dataset.v;
  if(t.tagName==="SELECT"||t.tagName==="INPUT")return;
  switch(a){
    case"tab":stack.length=0;route={...route,tab:v,sid:null};render();break;
    case"back":goBack();break;
    case"open":go("students",{sid:v});break;
    case"fa":route.fa=v;render();break;
    case"goto":go(v);break;
    case"installApk":if(window.__pendingApk)NU.install(window.__pendingApk);break;
    case"finMonth":route.fin=v;go("fin");break;
    case"stFin":route.fin=curCyc(v);go("fin");break;
    case"stLessons":route.lsid=v;route.lm="";go("lessons",{sid:null});break;
    case"lsidc":route.lsid=v;render();break;
    case"lmc":route.lm=v;render();break;
    case"addStudent":studentForm();break;
    case"editStudent":studentForm(sOf(v));break;
    case"archive":{const s=sOf(v);s.archived=!s.archived;s.archivedAt=s.archived?today():null;save();toast(s.archived?"اتأرشف":"اترجّع");route.sid=null;stack.length=0;render();break}
    case"delStudent":{const s=sOf(v);if(confirm(`تمسح "${s.name}" نهائي مع كل حصصه ودفعاته؟ (الأرشفة أأمن)`)){db.students=db.students.filter(x=>x.id!==v);db.lessons=db.lessons.filter(l=>l.sid!==v);db.payments=db.payments.filter(p=>p.sid!==v);save();route.sid=null;stack.length=0;toast("اتمسح");render()}break}
    case"addLesson":lessonForm();break;
    case"lessonFor":lessonForm(v);break;
    case"editLesson":lessonForm(null,db.lessons.find(l=>l.id===v));break;
    case"delLesson":if(confirm("تمسح الحصة دي؟")){db.lessons=db.lessons.filter(l=>l.id!==v);save();closeModal();render();toast("اتمسحت")}break;
    case"addRev":{const d=document.createElement("div");d.innerHTML=`<div class="rev" data-rev><select name="rs" data-role="sur">${surahOpts(0)}</select><input type="number" name="rf" inputmode="numeric" placeholder="من" min="1"><input type="number" name="rt" inputmode="numeric" placeholder="إلى" min="1"><button type="button" class="ibtn red" data-a="rmRev">${ic("x")}</button></div>`;$("#revs").appendChild(d.firstChild);break}
    case"rmRev":t.closest("[data-rev]").remove();break;
    case"star":{const g=+v;$("#grade").value=$("#grade").value==g?0:g;document.querySelectorAll("#stars button").forEach((x,i)=>x.classList.toggle("on",i<+$("#grade").value));break}
    case"close":closeModal();break;
    case"addPay":payForm(v);break;
    case"delPay":if(confirm("تمسح الدفعة دي؟")){db.payments=db.payments.filter(p=>p.id!==v);save();render()}break;
    case"addExp":expForm();break;
    case"delExp":if(confirm("تمسح المصروف ده؟")){db.expenses=db.expenses.filter(p=>p.id!==v);save();render()}break;
    case"fm":route.fin=addM(route.fin,-(+v));render();break;
    case"export":exportData();break;
    case"import":$("#imp").click();break;
    case"chkUpd":db.settings.updateUrl=$("#upd").value.trim();save();checkUpdate(true);break;
    case"restore":if(confirm("ترجّع البيانات من النسخة دي؟ البيانات الحالية هتتبدّل.")){try{snapshot(db,"قبل الاسترجاع");db=JSON.parse(localStorage.getItem(v));localStorage.setItem(KEY,JSON.stringify(db));toast("اترجّعت النسخة");render()}catch(x){toast("النسخة دي تالفة")}}break;
    case"wipe":if(confirm("هتمسح كل البيانات نهائي. متأكد؟")&&confirm("تأكيد أخير: مفيش رجوع.")){snapshot(db,"قبل المسح");db={ver:VER,students:[],lessons:[],payments:[],expenses:[],settings:db.settings};save();toast("اتمسح كل حاجة");render()}break;
  }
});
